def compressir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    result = []
    i = 0
    n = len(texto)
    while i < n:
        ch = texto[i]
        count = 1
        i += 1
        while i < n and texto[i] == ch:
            count += 1
            i += 1
        result.append(f"{ch}{count}")
    return "".join(result)
